css:
/* 背後にもう1枚（疑似要素1つで済む） */
.sheet{position:relative; isolation:isolate; border-radius:14px}
.sheet::before{content:""; position:absolute; z-index:-1;
  inset:-16px -10px 24px -4px;              /* 上と左を厚く＝楔形にのぞく */
  background:#f6dfe2; border-radius:14px; transform:rotate(-1.5deg)}

/* 中身なしの空フレーム版 */
.photo::before{content:""; position:absolute; z-index:-1;
  inset:-16px -16px 16px 16px; background:#fff;
  border:1px solid #dcdcdc; border-radius:14px}

/* 逆向き傾き＋画面端で断ち落とし */
.deck{overflow:hidden}
.deck .card{box-shadow:0 10px 24px rgba(0,0,0,.10); border:0}
.deck .card:nth-child(1){transform:rotate(-3deg); margin-left:-48px}
.deck .card:nth-child(2){transform:rotate(2deg);  margin-left:-72px; z-index:2}

/* 階段状に8pxだけ重ねる（3枚） */
.row{display:grid; grid-template-columns:repeat(3,auto)}
.row > *{margin-left:-8px; border-radius:20px}
.row > *:nth-child(1){transform:translateY(24px)}
.row > *:nth-child(2){transform:translateY(64px); z-index:2}
